SELECT CAST(COUNT(*) AS decimal(10,2)) / COUNT(DISTINCT e.CustomerID) AS AvgPerCustomer
FROM retail_logistics.ShipmentPackages AS li
JOIN retail_logistics.Shipments AS e ON e.ShipmentID = li.ShipmentID;

SELECT DISTINCT
       PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY FreightCharge) OVER () AS MedianFreightCharge
FROM retail_logistics.Shipments;

SELECT ShipmentID, ShipDate,
